    def sumScores(self, s):
        # Template: https://cp-algorithms.com/string/z-function.html
        def z_function(s):  # Time: O(n), Space: O(n)
            z = [0]*len(s)
            l, r = 0, 0
            for i in range(1, len(z)):
                if i <= r:
                    z[i] = min(r-i+1, z[i-l])
                while i+z[i] < len(z) and s[z[i]] == s[i+z[i]]:
                    z[i] += 1
                if i+z[i]-1 > r:
                    l, r = i, i+z[i]-1
            return z

        z = z_function(s)
        z[0] = len(s)
        return sum(z)

class Solution:
    def convertTime(self, current: str, correct: str) -> int:
        def get_time(t):
            hh, mm = t.split(':')
            return int(hh) * 60 + int(mm)

        current, correct = get_time(current), get_time(correct)
        operations = 0
        diff = correct - current

        for mins in [60, 15, 5, 1]:
            quotient, remainder = divmod(diff, mins)
            operations += quotient
            diff = remainder

        return operations

class Solution:
    def convertTime(self, current: str, correct: str) -> int:
        OPS = (60, 15, 5, 1)
        diff = (int(correct[:2])*60+int(correct[3:]))-(int(current[:2])*60+int(current[3:]))
        result = 0
        for x in OPS:
            q, diff = divmod(diff, x)
            result += q
        return result

